-- Watches each supported game's saves; writes only this plugin's Millennium configuration.
-- Each game pack (games.lua, generated by source/build.py) names a detector module that
-- implements locate/resolve/parse/evaluate/counts/describe. Games without a detector
-- are manual-only and never touch the disk.
local millennium = require('millennium')
local fs = require('fs')
local json = require('json')
local games = require('games')
local detectors = { ac1 = require('detector_ac1'), ac2 = require('detector_ac2'), cod = require('detector_cod'), fable3 = require('detector_fable3'),
    me1 = require('detector_me1'), me2 = require('detector_me2'), acb = require('detector_acb'),
    thrillville = require('detector_thrillville'), fallout3 = require('detector_fallout3') }
-- A save a detector does not expect (corrupt, cut off, a new game version) must not break
-- tracking: an error while parsing is reported like any unsupported save. The detectors call
-- D.parse themselves while picking a save, so the guard goes on the module.
local function parsed_or_reason(ok, ...)
    if ok then return ... end
    return nil, 'Could not read this save (' .. tostring((...)) .. ').'
end
for _, detector in pairs(detectors) do
    detector.rawParse = detector.rawParse or detector.parse
    detector.parse = function(...) return parsed_or_reason(pcall(detector.rawParse, ...)) end
end
local readers = { acb = require('decoder_acb'), thrillville = require('decoder_thrillville') }
local recorder = require('recorder')
local capture = require('capture')
local LOCATE_INTERVAL = 10
-- This file's folder, so record mode can write next to the plugin (backend\..\recordings).
local SCRIPT = debug and debug.getinfo and (debug.getinfo(1, 'S').source or '') or ''

local function safe_list(path)
    local ok, entries = pcall(fs.list, path)
    return ok and type(entries) == 'table' and entries or {}
end

local function read_small(path, limit)
    local file = io.open(path, 'rb')
    if not file then return nil end
    local bytes = file:read(limit + 1)
    file:close()
    if not bytes or #bytes > limit then return nil end
    return bytes
end

-- Steam libraries can live on another drive. Read only their install metadata.
local function steam_libraries()
    local steam = millennium.steam_path()
    local libraries, seen = {}, {}
    local function add(path)
        if path and not seen[path] then seen[path], libraries[#libraries + 1] = true, path end
    end
    add(steam)
    local vdf = read_small(fs.join(steam, 'steamapps', 'libraryfolders.vdf'), 1048576)
    if vdf then
        for value in vdf:gmatch('"path"%s*"([^"]+)"') do add((value:gsub('\\\\', '\\'))) end
    end
    return libraries
end

local function install_dirs(appId)
    local found = {}
    for _, library in ipairs(steam_libraries()) do
        local manifest = read_small(fs.join(library, 'steamapps', 'appmanifest_' .. appId .. '.acf'), 1048576)
        local directory = manifest and manifest:match('"installdir"%s*"([^"]+)"')
        if directory and not directory:find('..', 1, true) and not directory:find('[\\/]') then
            found[#found + 1] = fs.join(library, 'steamapps', 'common', directory)
        end
    end
    return found
end

local function context(game)
    return { fs = fs, safe_list = safe_list, read_small = read_small, getenv = os.getenv,
        install_dirs = function() return install_dirs(game.appId) end }
end

local function supported_for(game, detector)
    if game.supported then return game.supported end
    if game.rules then
        local list = {}
        for _, rule in ipairs(game.rules) do list[#list + 1] = rule.index end
        table.sort(list)
        return list
    end
    return detector.supported or {}
end

local watchers, order = {}, {}

local function new_watcher(game)
    local detector = detectors[game.detector]
    local w = { game = game, detector = detector, ctx = context(game), automatic = {}, held = {},
        configuredPath = '', lastLocate = -LOCATE_INTERVAL, lastPoll = 0 }
    w.state = { schemaVersion = 1, appId = game.appId, status = detector and 'searching' or 'manual',
        message = detector and ('Looking for ' .. game.title .. ' progress') or 'Manual tracking only.',
        supportedIndices = detector and supported_for(game, detector) or {},
        progress = w.automatic, saveFound = false, recordCount = 0 }
    return w
end

for _, game in ipairs(games) do
    local w = new_watcher(game)
    watchers[game.appId] = w
    order[#order + 1] = w
end

-- A detector may read more than the save itself (Brotherhood adds the OPTIONS file).
local function read_progress(w, path)
    if w.detector.read then return w.detector.read(w.ctx, path) end
    return read_small(path, w.detector.maxBytes)
end

local function select_path(w)
    local state = w.state
    -- Searching opens many files, so a missing save is looked for again only every few seconds.
    local now = os.time()
    if now - w.lastLocate < LOCATE_INTERVAL then return nil end
    w.lastLocate = now
    if w.configuredPath ~= '' then
        local path, reason, note, saves = w.detector.resolve(w.ctx, w.configuredPath, w.game)
        -- A chosen slot file stands for its folder: the newest slot written there is the game
        -- being played, so a new game or another loaded slot is followed.
        if path and w.detector.followFolder then
            local newest, _, _, all = w.detector.resolve(w.ctx, fs.parent_path(path), w.game)
            if newest then path, saves = newest, all or saves end
        end
        state.selectionIssue = reason
        if note then state.selectionNote = note end
        if saves then state.availableSaves = saves end
        return path
    end
    state.selectionIssue = nil
    local path, saves = w.detector.locate(w.ctx, w.game)
    if saves then state.availableSaves = saves end
    return path
end

local function held_key(game) return game.progressKey .. '_held' end
local function held_path_key(game) return game.progressKey .. '_heldPath' end

local function apply(w, parsed)
    local state, game, detector = w.state, w.game, w.detector
    local changed, earned = false, {}
    for _, index in ipairs(detector.evaluate(parsed, game)) do earned[tostring(index)] = true end
    -- After "Reset to locked", what the save already had stays locked until a save no
    -- longer has it (an older save or a new game); earning it again then unlocks it.
    -- Held keys belong to the save that was open at the reset; another save file (a new
    -- game in another slot) releases them all.
    local released, other = false, w.heldPath ~= w.selectedPath
    for key in pairs(w.held) do
        if other or not earned[key] then w.held[key], released = nil, true end
    end
    if released then millennium.config.set(held_key(game), w.held) end
    for key in pairs(earned) do
        if not w.automatic[key] and not w.held[key] then
            w.automatic[key] = os.date('!%Y-%m-%dT%H:%M:%SZ')
            changed = true
        end
    end
    if changed then millennium.config.set(game.progressKey, w.automatic) end
    state.recordCount = parsed.recordCount or 0
    state.missionRecords, state.slot = parsed.missionRecords, parsed.slot
    state.counts = detector.counts(parsed, game)
    w.lastParsed = parsed
end

local function describe(w)
    local state = w.state
    state.status, state.message, state.details = w.detector.describe(w.lastParsed, state.saveFileName, w.game)
end

local function poll(w)
    local state = w.state
    if not w.detector then return json.encode(state) end
    local now = os.time()
    if w.cachedReply and now == w.lastPoll then return w.cachedReply end
    w.lastPoll = now
    -- Re-check every few seconds, so a new save slot (a new game) is picked up while Steam runs.
    local found = select_path(w)
    if found then w.selectedPath = found end
    state.pathConfigured = w.configuredPath ~= ''
    state.lastScan = now
    state.progress = w.automatic
    if not w.selectedPath then
        state.status, state.saveFound = 'no-save', false
        state.message = 'No ' .. w.game.title .. ' progress file found yet. ' .. (w.game.setupHint or 'Select it in Settings.')
        if state.selectionIssue == 'path-not-found' then state.message = 'Path not found. Paste the full file or folder path.' end
    else
        local bytes = read_progress(w, w.selectedPath)
        state.saveFound = bytes ~= nil
        state.saveFileName = fs.filename(w.selectedPath)
        state.saveBytes = bytes and #bytes or 0
        if not bytes then
            state.status, state.message = 'save-unavailable', 'The selected file could not be read. Retrying.'
            w.pendingBytes = nil
        elseif bytes ~= w.pendingBytes then
            -- Award only from a snapshot that is identical across two polls.
            w.pendingBytes = bytes
            state.status, state.message = 'stabilizing', 'Waiting for the save to finish writing.'
        elseif bytes ~= w.parsedBytes then
            local parsed, reason = w.detector.parse(bytes, w.game)
            local ok, err = true, nil
            if parsed then ok, err = pcall(apply, w, parsed) end
            if not parsed or not ok then
                state.status, state.message = 'unsupported-save', reason or ('Could not check this save (' .. tostring(err) .. ').')
            else
                describe(w)
                w.parsedBytes = bytes
            end
        else
            describe(w)
        end
    end
    w.cachedReply = json.encode(state)
    return w.cachedReply
end

-- Millennium passes the JS argument object's single value. Older builds of the
-- frontend called GetTrackerState() with no arguments and SetSavePath(path) for AC2.
local function request(value)
    if type(value) == 'table' then value = value.payload or value[1] end
    if type(value) == 'string' and value:sub(1, 1) == '{' then
        local ok, decoded = pcall(json.decode, value)
        if ok and type(decoded) == 'table' then return decoded end
    end
    return { appId = 33230, path = type(value) == 'string' and value or nil }
end

local function watcher_for(appId)
    local w = watchers[tonumber(appId) or 33230]
    if not w then error('Unknown game ' .. tostring(appId)) end
    return w
end

-- Exports are globals because Millennium's legacy Lua FFI resolves global names.
function SetSavePath(payload)
    local req = request(payload)
    local w = watcher_for(req.appId)
    if not w.detector then error('This game has no automatic tracking yet') end
    local path = req.path
    if type(path) ~= 'string' or #path > 2048 then error('Expected a local file or folder path') end
    path = path:match('^%s*(.-)%s*$'):gsub('^"(.*)"$', '%1')
    w.state.selectionNote, w.state.availableSaves, w.state.selectionIssue = nil, nil, nil
    if path ~= '' then
        local resolved, reason, note, saves = w.detector.resolve(w.ctx, path, w.game)
        w.state.selectionNote, w.state.availableSaves = note, saves
        if resolved then path = resolved
        elseif reason ~= 'no-gameplay-save' then error(reason or 'Cannot read that file') end
    end
    w.configuredPath, w.selectedPath, w.lastLocate = path, nil, -LOCATE_INTERVAL
    w.pendingBytes, w.parsedBytes, w.cachedReply = nil, nil, nil
    millennium.config.set(w.game.pathKey, path)
    return poll(w)
end

local function clean_text(value, limit)
    if type(value) ~= 'string' then return '' end
    return (value:gsub('[%c]', ' '):sub(1, limit))
end

local function writable(folder)
    if not folder or not fs.is_directory(folder) then return false end
    local probe = fs.join(folder, '.write-test')
    local file = io.open(probe, 'wb')
    if not file then return false end
    file:close()
    os.remove(probe)
    return true
end

-- The plugin's own recordings folder (shipped in the package), else the user's temp folder.
local function recordings_folder()
    local script = SCRIPT:match('^@(.+)$')
    if script then
        local backend = script:match('^(.*)[\\/][^\\/]+$')
        local plugin = backend and backend:match('^(.*)[\\/][^\\/]+$')
        if plugin and writable(fs.join(plugin, 'recordings')) then return fs.join(plugin, 'recordings') end
    end
    local temp = os.getenv('TEMP') or os.getenv('TMP')
    if writable(temp) then return temp end
    return nil
end

-- Named values for record mode and capture: the detector's, else the pack's save reader.
local function save_decoders(w)
    if w.detector and w.detector.decoders then return w.detector.decoders(w.game) end
    local reader = readers[w.game.decoder]
    return reader and reader.decoders(w.game) or {}
end

-- Manual games may name where their saves usually are (games.lua saveFolders).
local function known_folder(w)
    for _, parts in ipairs(w.game.saveFolders or {}) do
        local base = os.getenv(parts[1])
        -- "*" matches any one subfolder (Ubisoft Connect puts an account id there).
        local function walk(path, i)
            if i > #parts then return fs.is_directory(path) and path or nil end
            if parts[i] ~= '*' then return walk(fs.join(path, parts[i]), i + 1) end
            for _, entry in ipairs(safe_list(path)) do
                if entry.is_directory and not entry.is_symlink then
                    local found = walk(entry.path, i + 1)
                    if found then return found end
                end
            end
            return nil
        end
        local found = base and walk(base, 2)
        if found then return found end
    end
    return nil
end

local function default_folder(w)
    if not w.detector then return known_folder(w) end
    if not w.selectedPath then w.lastLocate = -LOCATE_INTERVAL; w.selectedPath = select_path(w) end
    return w.selectedPath and fs.parent_path(w.selectedPath) or nil
end

function StartRecording(payload)
    local req = request(payload)
    local w = watcher_for(req.appId)
    local index = tonumber(req.index)
    if not index or index < 0 or index ~= math.floor(index) then error('Pick an achievement first') end
    local folder = type(req.folder) == 'string' and req.folder:match('^%s*"?(.-)"?%s*$') or ''
    if #folder > 2048 then error('Folder path is too long') end
    if folder == '' then folder = default_folder(w) end
    if not folder then error('Paste the folder where ' .. w.game.title .. ' keeps its saves') end
    if not fs.is_directory(folder) then error('Folder not found. Paste the full save folder path.') end
    local before = recorder.snapshot(w.ctx, folder)
    if before.count == 0 then error('No files in that folder') end
    w.recording = { before = before, folder = folder, index = index, name = clean_text(req.name, 200),
        detail = clean_text(req.detail, 400), started = os.date('%Y-%m-%d %H:%M:%S') }
    -- Narrowing continues only for the same achievement and folder, and only when asked.
    local n = w.narrowing
    if not req.narrow or not n or n.index ~= index or n.folder ~= folder then
        w.narrowing = { index = index, folder = folder, passes = 0, progressPasses = 0, excluded = {} }
    end
    return json.encode({ recording = true, appId = w.game.appId, index = index, folderName = fs.filename(folder),
        files = before.count, bytes = before.bytes, skipped = before.skipped, started = w.recording.started,
        previousPasses = w.narrowing.passes })
end

function CancelRecording(payload)
    local w = watcher_for(request(payload).appId)
    w.recording = nil
    return json.encode({ recording = false, appId = w.game.appId })
end

local function rule_verdict(w, index)
    if not w.detector then return nil end
    local supported = false
    for _, i in ipairs(w.state.supportedIndices) do if i == index then supported = true end end
    if not supported then return 'none (this achievement is marked by hand)' end
    local path = w.selectedPath or default_folder(w) and w.selectedPath
    local bytes = path and read_progress(w, path)
    local parsed = bytes and w.detector.parse(bytes, w.game)
    if not parsed then return 'could not read ' .. (path and fs.filename(path) or 'the save') .. ' to check it' end
    for _, earned in ipairs(w.detector.evaluate(parsed, w.game)) do
        if earned == index then return 'unlocked by the plugin' end
    end
    local count = w.detector.counts(parsed, w.game)[tostring(index)]
    if count then return string.format('not yet: %s / %s %s', count.have, count.need, count.label or '') end
    return 'not unlocked yet'
end

function FinishRecording(payload)
    local req = request(payload)
    local w = watcher_for(req.appId)
    local rec = w.recording
    if not rec then error('Nothing is being recorded. Press Start first.') end
    local noProgress = req.noProgress == true
    local after = recorder.snapshot(w.ctx, rec.folder)
    local targets = recorder.targets(rec.detail)
    local decoders = save_decoders(w)
    local files, matches = recorder.compare(rec.before, after, targets, decoders)
    local narrowing = recorder.narrow(w.narrowing, files, noProgress)
    recorder.trim(files)
    local report = { schemaVersion = 1, appId = w.game.appId, game = w.game.title, index = rec.index,
        achievement = rec.name, detail = rec.detail, targets = targets, started = rec.started,
        finished = os.date('%Y-%m-%d %H:%M:%S'), folderName = fs.filename(rec.folder),
        filesWatched = after.count, files = files, matches = matches, rule = rule_verdict(w, rec.index),
        noProgress = noProgress or nil, narrowing = narrowing }
    local stem = (w.game.title .. ' ' .. os.date('%Y-%m-%d %H%M%S') .. ' ' .. rec.name)
        :gsub('[\\/:*?"<>|%c]', ''):sub(1, 90)
    local out = recordings_folder()
    local saved = out and recorder.save(out, fs.join, stem, rec.before, after, report, json.encode)
    w.recording = nil
    report.savedTo = saved and out or nil
    report.savedFiles = saved and #saved or 0
    return json.encode(report)
end

-- Capture copies go to recordings\<game>\ when that folder exists, else into
-- recordings\ (or temp) with the game's name in front of each file.
local function capture_output(w)
    local root = recordings_folder()
    if not root then return nil, '' end
    local own = fs.join(root, w.game.slug or tostring(w.game.appId))
    if writable(own) then return own, '' end
    return root, (w.game.slug or tostring(w.game.appId)) .. ' capture '
end

local function capture_key(w) return 'capture_' .. w.game.appId .. '_v1' end

-- An empty choice follows the tracked save's folder, found on the first tick if not now.
local function start_capture(w, chosen, resolve)
    local folder = chosen ~= '' and chosen or (resolve and default_folder(w)) or nil
    w.capture = capture.new(folder or '')
    w.capture.chosen = chosen
    w.captureOut, w.capturePrefix = capture_output(w)
    if w.captureOut then capture.measure(w.capture, w.ctx, w.captureOut, w.capturePrefix) end
    if not folder then w.capture.problem = 'Waiting for the save folder' end
end

local function capture_tick(w)
    local cap = w.capture
    if not cap then return end
    if cap.folder == '' then
        local folder = default_folder(w)
        if not folder then cap.problem = 'Waiting for the save folder'; return end
        cap.folder = folder
    end
    local decoders = save_decoders(w)
    local unlocked = 0
    for _ in pairs(w.automatic) do unlocked = unlocked + 1 end
    local extra = w.detector and ('[' .. unlocked .. ' automatic unlocks' .. (w.state.details and ('; ' .. w.state.details) or '') .. ']') or nil
    capture.tick(cap, w.ctx, os.time(), w.captureOut, w.capturePrefix, fs.join, decoders, extra)
end

function GetTrackerState(payload)
    local w = watcher_for(request(payload).appId)
    if w.capture then
        capture_tick(w)
        if w.capture.enabled == false then
            millennium.config.set(capture_key(w), { enabled = false })
        end
    end
    w.state.capture = w.capture and capture.summary(w.capture, fs) or nil
    if not w.detector then return json.encode(w.state) end
    return poll(w)
end

-- Locks every automatic unlock again. Achievements the current save already earns are
-- held back (see apply), so testing starts from an older save or a new game.
function ResetProgress(payload)
    local w = watcher_for(request(payload).appId)
    if not w.detector then return json.encode(w.state) end
    local held = {}
    local path = w.selectedPath or select_path(w)
    local bytes = path and read_progress(w, path)
    local parsed = bytes and w.detector.parse(bytes, w.game)
    if parsed then
        for _, index in ipairs(w.detector.evaluate(parsed, w.game)) do held[tostring(index)] = true end
    end
    w.automatic, w.held, w.heldPath = {}, held, path
    w.state.progress = w.automatic
    millennium.config.set(w.game.progressKey, w.automatic)
    millennium.config.set(held_key(w.game), w.held)
    millennium.config.set(held_path_key(w.game), path or '')
    w.parsedBytes, w.cachedReply = nil, nil
    return poll(w)
end

function GetCaptureList()
    local list = {}
    for _, w in ipairs(order) do
        if w.capture and w.capture.enabled then list[#list + 1] = w.game.appId end
    end
    return json.encode({ schemaVersion = 1, captures = list })
end

function SetCapture(payload)
    local req = request(payload)
    local w = watcher_for(req.appId)
    if req.enabled then
        local folder = type(req.folder) == 'string' and req.folder:match('^%s*"?(.-)"?%s*$') or ''
        if #folder > 2048 then error('Folder path is too long') end
        if folder ~= '' and not fs.is_directory(folder) then error('Folder not found. Paste the full save folder path.') end
        if folder == '' and not w.detector and not known_folder(w) then error('Paste the folder where ' .. w.game.title .. ' keeps its saves') end
        start_capture(w, folder, true)
        if not w.captureOut then w.capture = nil; error('No folder to save captures in') end
        millennium.config.set(capture_key(w), { enabled = true, folder = folder })
    else
        w.capture = nil
        millennium.config.set(capture_key(w), { enabled = false })
    end
    w.cachedReply = nil
    return GetTrackerState(payload)
end

local function on_load()
    for _, w in ipairs(order) do
        if w.detector then
            local saved = millennium.config.get(w.game.progressKey)
            if type(saved) == 'table' then
                for _, index in ipairs(w.state.supportedIndices) do
                    local value = saved[tostring(index)]
                    if type(value) == 'string' then w.automatic[tostring(index)] = value end
                end
            end
            local held = millennium.config.get(held_key(w.game))
            w.heldPath = millennium.config.get(held_path_key(w.game))
            -- Keys held by v0.9.1-v0.10.1 have no save recorded, so they are not kept.
            if type(held) == 'table' and type(w.heldPath) == 'string' and w.heldPath ~= '' then
                for _, index in ipairs(w.state.supportedIndices) do
                    if held[tostring(index)] == true then w.held[tostring(index)] = true end
                end
            end
            local path = millennium.config.get(w.game.pathKey)
            if type(path) == 'string' then w.configuredPath = path end
        end
        local saved = millennium.config.get(capture_key(w))
        if type(saved) == 'table' and saved.enabled == true then
            start_capture(w, type(saved.folder) == 'string' and saved.folder or '', false)
        end
    end
    millennium.ready()
end

return { on_load = on_load }
